PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PrevLevel : INT := 0;
END_VAR

// Check if the level has changed significantly to avoid oscillation
IF Level <> PrevLevel THEN
    PrevLevel := Level;

    // Turn off PumpIn if the level reaches or exceeds HighLimit
    IF Level >= HighLimit THEN
        PumpIn := FALSE;
        ValveOut := TRUE; // Open the outlet valve to prevent overflow
    ELSIF Level <= LowLimit THEN
        PumpIn := TRUE; // Start the inlet pump
        ValveOut := FALSE; // Close the outlet valve
    ELSE
        PumpIn := FALSE; // Stop the inlet pump
        ValveOut := FALSE; // Close the outlet valve
    END_IF;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LastLevel : INT := 0;
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

// Check if the level has changed since last time
IF Level <> LastLevel THEN
    // Reset the timer
    PumpTimer(IN := TRUE, PT := T#5s);
END_IF;

LastLevel := Level;

// Safety check: never run PumpIn when Level >= HighLimit
IF Level >= HighLimit THEN
    PumpIn := FALSE;
ELSE
    // Control logic based on hysteresis
    IF Level <= LowLimit THEN
        PumpIn := TRUE;
        ValveOut := FALSE;
    ELSIF Level >= HighLimit THEN
        PumpIn := FALSE;
        ValveOut := TRUE;
    ELSE
        PumpIn := FALSE;
        ValveOut := FALSE;
    END_IF;
END_IF;

// Update ValveOut based on safety check
IF Level >= HighLimit THEN
    ValveOut := TRUE;
END_IF;

// Assign output after safety checks
PumpIn := NOT (Level >= HighLimit AND PumpTimer.Q);

END_PROGRAM

