PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    Prev_OpenA_Cmd : BOOL := FALSE;
    Prev_OpenB_Cmd : BOOL := FALSE;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := TRUE, PT := T#1s);

IF NOT SafetyTimer.Q THEN
    DoorA := FALSE;
    DoorB := FALSE;
ELSE
    IF OpenA_Cmd AND NOT OpenB_Cmd THEN
        DoorA := TRUE;
        DoorB := FALSE;
    ELSIF OpenB_Cmd AND NOT OpenA_Cmd THEN
        DoorA := FALSE;
        DoorB := TRUE;
    ELSE
        DoorA := FALSE;
        DoorB := FALSE;
    END_IF;

    IF OpenA_Cmd <> Prev_OpenA_Cmd OR OpenB_Cmd <> Prev_OpenB_Cmd THEN
        SafetyTimer(IN := TRUE, PT := T#1s);
    END_IF;
END_IF;

Prev_OpenA_Cmd := OpenA_Cmd;
Prev_OpenB_Cmd := OpenB_Cmd;
END_PROGRAM

