PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := NOT (GuardClosed OR Fault), PT := T#1s);

CASE SafetyTimer.Q OF
    TRUE:
        IF StartPB AND NOT Running THEN
            Running := TRUE;
        ELSIF StopPB OR NOT GuardClosed OR Fault THEN
            Running := FALSE;
        END_IF;
    ELSE
        Running := FALSE;
    END_CASE;

Conveyor := Running;
END_PROGRAM

