        T_Yellow.PT := T#1s;
        T_AllRed.PT := T#2s;
    2, 5:
        T_Green.PT := T#1s;
        T_Yellow.PT := T#1s;
        T_AllRed.PT := T#2s;
END_CASE;

// Reset timers when state changes
T_Green(IN := FALSE);
T_Yellow(IN := FALSE);
T_AllRed(IN := FALSE);

// Update timers based on current state
CASE State OF
    0:
        T_Green(IN := TRUE);
        NS_G := T_Green.Q;
        NS_Y := NOT T_Green.Q AND NOT T_Yellow.Q;
        NS_R := NOT T_Green.Q AND NOT T_Yellow.Q;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    1:
        T_Yellow(IN := TRUE);
        NS_G := FALSE;
        NS_Y := T_Yellow.Q;
        NS_R := NOT T_Yellow.Q AND NOT T_Green.Q;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    2:
        T_AllRed(IN := TRUE);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := T_AllRed.Q;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := T_AllRed.Q;
    3:
        T_Green(IN := TRUE);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := NOT T_Green.Q AND NOT T_Yellow.Q;
        EW_G := T_Green.Q;
        EW_Y := NOT T_Green.Q AND NOT T_Yellow.Q;
        EW_R := NOT T_Green.Q AND NOT T_Yellow.Q;
    4:
        T_Yellow(IN := TRUE);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := NOT T_Yellow.Q AND NOT T_Green.Q;
        EW_G := FALSE;
        EW_Y := T_Yellow.Q;
        EW_R := NOT T_Yellow.Q AND NOT T_Green.Q;
    5:
        T_AllRed(IN := TRUE);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := T_AllRed.Q;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := T_AllRed.Q;
END_CASE;

// Safety check: ensure only one direction can move at a time
ASSERT NOT (NS_G OR EW_G) OR (NOT NS_G AND NOT EW_G);
ASSERT NOT (NS_Y OR EW_Y) OR (NOT NS_Y AND NOT EW_Y);
ASSERT NOT (NS_R OR EW_R) OR (NOT NS_R AND NOT EW_R);

END_PROGRAM

