    Motor := FALSE;
    StartTimer(IN := FALSE);
    HoldCount := 0;
ELSIF StartCmd THEN
    StartTimer(IN := TRUE, PT := T#1s); // Preset to 1 second tick
    IF StartTimer.Q AND (HoldCount < TargetHoldCount) THEN
        HoldCount := HoldCount + 1;
    ELSE
        Motor := TRUE;
    END_IF;
ELSE
    Motor := FALSE;
    StartTimer(IN := FALSE);
    HoldCount := 0;
END_IF;

