        Pump := FALSE;
        Valve := FALSE;
        IF StartCycle AND NOT EStop THEN
            IF Level < 90 THEN
                State := 1;
                FillTimer(IN := TRUE, PT := T#5s);
            END_IF;
        END_IF;

    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF EStop THEN
            State := 0;
        ELSIF Level >= 90 THEN
            State := 2;
            DrainTimer(IN := TRUE, PT := T#5s);
        END_IF;

    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF EStop THEN
            State := 0;
        ELSIF Level <= 10 THEN
            State := 0;
        END_IF;
END_CASE;

// Safety checks
IF Pump AND Valve THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;

IF Level >= 90 AND Pump THEN
    State := 0;
    Pump := FALSE;
END_IF;

IF Level <= 10 AND Valve THEN
    State := 0;
    Valve := FALSE;
END_IF;
END_PROGRAM

