    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF Level <= 10 OR EStop THEN
            State := 0;
        END_IF;
END_CASE;

// Ensure safety conditions are met
IF Pump AND Valve THEN
    State := 0; // Reset to idle if both are on
    Pump := FALSE;
    Valve := FALSE;
END_IF;

IF Level >= 90 AND Pump THEN
    State := 0; // Reset to idle if filling above high level
    Pump := FALSE;
END_IF;

IF Level <= 10 AND Valve THEN
    State := 0; // Reset to idle if draining below low level
    Valve := FALSE;
END_IF;

END_PROGRAM

