    Prev_LH : BOOL := FALSE;
    Prev_RH : BOOL := FALSE;
    ArmTimer : TON;
END_VAR

// Update previous states
Prev_LH := LH;
Prev_RH := RH;

// Check if both buttons were previously pressed and now released
IF Prev_LH AND Prev_RH AND NOT LH AND NOT RH THEN
    // Reset arm timer
    ArmTimer(IN := TRUE, PT := T#2s);
END_IF;

// Check if both buttons are pressed and arm timer has elapsed
IF LH AND RH AND ArmTimer.Q THEN
    Actuator := TRUE;
ELSE
    Actuator := FALSE;
END_IF;

// Handle tie-down prevention
IF LH XOR RH THEN
    Armed := FALSE;
ELSIF NOT LH AND NOT RH THEN
    Armed := TRUE;
END_IF;

