    EStopTimer(IN := TRUE);
ELSE
    EStopTimer(IN := FALSE);
END_IF;

// Handle StopPB override
IF StopPB THEN
    State := 0;
END_IF;

// Sequential启动控制
CASE State OF
    0:
        // All off
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;

        IF EStopTimer.Q OR StartPB THEN
            IF StartPB AND NOT EStopTimer.Q THEN
                State := 1;
            END_IF;
        END_IF;

    1:
        // C3 on
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;

        IF EStopTimer.Q OR (StartPB AND NOT EStopTimer.Q) THEN
            State := 2;
        END_IF;

    2:
        // C3 and C2 on
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;

        IF EStopTimer.Q OR (StartPB AND NOT EStopTimer.Q) THEN
            State := 3;
        END_IF;

    3:
        // All on
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;

        IF EStopTimer.Q OR StopPB THEN
            State := 0;
        END_IF;
END_CASE;

