PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State : INT := 0;
    TimerC3 : TON;
    TimerC2 : TON;
END_VAR

// Check for emergency stop
IF NOT EStop THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    TimerC3(IN := FALSE);
    TimerC2(IN := FALSE);
    EXIT;
END_IF;

// Handle StartPB and StopPB
IF StartPB AND NOT StopPB THEN
    CASE State OF
        0:
            IF TimerC3.Q THEN
                State := 1;
                TimerC3(IN := FALSE);
            END_IF;
        1:
            IF TimerC2.Q THEN
                State := 2;
                TimerC2(IN := FALSE);
            END_IF;
        2:
            IF TimerC3.Q THEN
                State := 3;
                TimerC2(IN := FALSE);
                TimerC3(IN := FALSE);
            END_IF;
        3:
            // Already running all
    END_CASE;
ELSIF StopPB THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    TimerC3(IN := FALSE);
    TimerC2(IN := FALSE);
END_IF;

// Update timers based on State
CASE State OF
    1:
        TimerC3(IN := TRUE, PT := T#2s);
        C1 := FALSE;
        C2 := FALSE;
        C3 := TimerC3.Q;
    2:
        TimerC3(IN := TRUE, PT := T#2s);
        TimerC2(IN := TRUE, PT := T#2s);
        C1 := FALSE;
        C2 := TimerC2.Q;
        C3 := TimerC3.Q;
    3:
        TimerC3(IN := TRUE, PT := T#2s);
        TimerC2(IN := TRUE, PT := T#2s);
        C1 := TimerC2.Q;
        C2 := TimerC2.Q;
        C3 := TimerC3.Q;
END_CASE;

END_PROGRAM

